1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"slices"
10		"strconv"
11		"unicode/utf8"
12	)
13	
14	// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
15	// truncated JSON, trailing data after the object, an unknown version,
16	// missing, mistyped, unknown, or duplicated fields, a null where version,
17	// tip, height, hash, parent, or a transaction identifier is required,
18	// heights that do not ascend consecutively from 1, an empty or duplicated
19	// hash, a broken parent link, a version-2 timestamp that is missing or
20	// neither null nor a non-negative integer, a hash, parent, or transaction
21	// identifier whose JSON string carries invalid UTF-8 bytes or unpaired or
22	// misordered Unicode surrogate escapes, or a tip that disagrees with the
23	// block list. A rejected restore never changes the index.
24	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
25	
26	const (
27		// snapshotVersion1 is the timestamp-less layout. It stays readable
28		// indefinitely; its blocks restore with missing timestamps.
29		snapshotVersion1 = 1
30		// snapshotVersion2 adds a required timestamp field to every block:
31		// either a non-negative Unix-seconds integer or null for missing time.
32		snapshotVersion2 = 2
33	)
34	
35	// snapshotDoc is the wire form of an exported main chain. Both layout
36	// versions share one shape: Version selects whether every block carries its
37	// Timestamp field.
38	type snapshotDoc struct {
39		Version int64           `json:"version"`
40		Tip     int64           `json:"tip"`
41		Blocks  []snapshotBlock `json:"blocks"`
42	}
43	
44	// snapshotBlock is the wire form of one block, shared by both versions.
45	// Height, hash, parent, and the transaction list follow the same rules in
46	// either layout. The timestamp is version 2 only and carried as a raw
47	// literal: nil is omitted altogether (version 1), "null" marks a missing
48	// time, and integer bytes render the Unix-seconds value (version 2). It
49	// stays the final field in every layout.
50	type snapshotBlock struct {
51		Height    int64           `json:"height"`
52		Hash      string          `json:"hash"`
53		Parent    string          `json:"parent"`
54		Txs       []string        `json:"txs"`
55		Timestamp json.RawMessage `json:"timestamp,omitempty"`
56	}
57	
58	// Export writes the current main chain to w as a JSON snapshot: a single
59	// object with version, tip, and the blocks ordered by ascending height, each
60	// carrying its transactions in order. The same main chain always produces
61	// the same bytes, regardless of the reorg, restore, or query history that
62	// led to it. Only blocks in effect at export time appear; nothing the index
63	// once held and later dropped is included.
64	//
65	// A chain whose blocks all lack timestamps keeps the original version-1
66	// layout, byte for byte. As soon as any block carries a timestamp the
67	// document is version 2 and every block includes a timestamp field: a
68	// non-negative integer or null for a missing timestamp.
69	//
70	// Export observes one complete chain state and never modifies the index.
71	// The chain is copied under the lock and serialized afterwards, so queries
72	// and appends proceed while the stream is still being written. A write
73	// failure is reported and leaves the index untouched.
74	func (index *Index) Export(w io.Writer) error {
75		doc := index.snapshotChain()
76		raw, err := json.Marshal(doc)
77		if err != nil {
78			panic(err) // snapshot docs only contain marshalable fields
79		}
80		n, err := w.Write(raw)
81		if err != nil {
82			return fmt.Errorf("indexroom: export snapshot: %w", err)
83		}
84		if n != len(raw) {
85			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
86		}
87		return nil
88	}
89	
90	// snapshotChain copies the current main chain into the export wire
91	// form: blocks by ascending height, each with its transactions copied in
92	// original order. This is the single place that turns stored blocks into the
93	// shared document fields, so both layout versions keep identical rules for
94	// height, hash, parent, and the transaction list; the only version-dependent
95	// field is the timestamp literal.
96	//
97	// The version is selected from the same chain copy. Any block carrying a
98	// timestamp — even a zero — makes the document version 2, after which every
99	// block gets a timestamp field, null where its time is missing; a chain
100	// whose blocks all lack times stays version 1 with no timestamp field.
101	func (index *Index) snapshotChain() snapshotDoc {
102		index.mu.Lock()
103		defer index.mu.Unlock()
104		version := int64(snapshotVersion1)
105		for height := int64(1); height <= index.Tip; height++ {
106			if index.Blocks[height].Time != nil {
107				version = snapshotVersion2
108				break
109			}
110		}
111		doc := snapshotDoc{
112			Version: version,
113			Tip:     index.Tip,
114			Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
115		}
116		for height := int64(1); height <= index.Tip; height++ {
117			block := index.Blocks[height]
118			txs := make([]string, len(block.Txs))
119			copy(txs, block.Txs)
120			entry := snapshotBlock{
121				Height: block.Height,
122				Hash:   block.Hash,
123				Parent: block.Parent,
124				Txs:    txs,
125			}
126			if version == snapshotVersion2 {
127				entry.Timestamp = snapshotTimestampLiteral(block.Time)
128			}
129			doc.Blocks = append(doc.Blocks, entry)
130		}
131		return doc
132	}
133	
134	// snapshotMissingTimestamp is the raw JSON literal written for a block whose
135	// time is missing in a version-2 document.
136	var snapshotMissingTimestamp = json.RawMessage("null")
137	
138	// snapshotTimestampLiteral renders a stored block time as its version-2
139	// timestamp literal: null for a missing time, otherwise its non-negative
140	// Unix-seconds value as a bare integer. Stored times are guaranteed
141	// non-negative by Append, Reorg, and Restore validation.
142	func snapshotTimestampLiteral(time *int64) json.RawMessage {
143		if time == nil {
144			return snapshotMissingTimestamp
145		}
146		return json.RawMessage(strconv.AppendInt(nil, *time, 10))
147	}
148	
149	// restoreAppliedHookLocked is a test-only rendezvous invoked from Restore
150	// once the snapshot chain has fully replaced the old main chain, while
151	// index.mu is still held and before the call returns. It is nil in
152	// production; restore regression tests park a successful restore here with
153	// the new chain already in effect, so a QueryTimeStats issued at that
154	// instant is forced to wait and, once it runs, must observe the complete
155	// new chain.
156	var restoreAppliedHookLocked func(newTip int64)
157	
158	// Restore replaces the whole main chain with the snapshot read from r. The
159	// input must be exactly one snapshot object, optionally followed by
160	// whitespace; every block is validated — including heights ascending from 1,
161	// non-empty unique hashes, and parent linkage — before anything is applied.
162	// The first block's parent is exempt from linkage: it names the chain start
163	// and need not be indexed.
164	//
165	// The replacement takes effect as one complete operation: on success the
166	// index holds exactly the snapshot chain with no leftover heights or hashes,
167	// and on any failure — a read error or an invalid block discovered at the
168	// very end — the current chain and every previously issued cursor remain as
169	// they were. The stream is consumed and validated before the lock is taken,
170	// so the index stays queryable and appendable while the restore is reading.
171	//
172	// After a successful restore, cursors issued earlier by this same index keep
173	// working wherever the pinned range still matches and the tip still covers
174	// it; otherwise continuations fail with ErrQueryChanged as usual.
175	func (index *Index) Restore(r io.Reader) error {
176		tip, blocks, err := parseSnapshot(r)
177		if err != nil {
178			return err
179		}
180		stored := make(map[int64]Block, len(blocks))
181		byHash := make(map[string]int64, len(blocks))
182		for _, block := range blocks {
183			stored[block.Height] = block
184			byHash[block.Hash] = block.Height
185		}
186		index.mu.Lock()
187		index.Blocks = stored
188		index.ByHash = byHash
189		index.Tip = tip
190		if restoreAppliedHookLocked != nil {
191			restoreAppliedHookLocked(tip)
192		}
193		index.mu.Unlock()
194		return nil
195	}
196	
197	// snapshotReader mediates between the snapshot's io.Reader and the JSON
198	// decoder so a fault the reader reports mid-document cannot be mistaken for a
199	// truncated document.
200	//
201	// json.Decoder turns a clean io.EOF after a partial JSON value into
202	// io.ErrUnexpectedEOF, and its token/peek path also drops any error that
203	// arrives together with the final bytes of a chunk. Either behavior makes a
204	// reader-reported io.ErrUnexpectedEOF — bare or wrapped — indistinguishable
205	// from an honestly truncated stream, and can hide the fault altogether.
206	//
207	// snapshotReader therefore observes every underlying read: only the bare
208	// io.EOF sentinel — the exact value, not anything that merely errors.Is-
209	// matches it — passes through as the normal end of input. A wrapped io.EOF,
210	// or a combined error such as errors.Join(io.EOF, fault), is a read failure
211	// like any other error: it is remembered in fault and, when it arrived
212	// together with bytes, withheld until the following read. The decoder
213	// consumes the delivered bytes first and then receives the fault as a
214	// separate error-only read, where it cannot be swallowed. The fault is
215	// sticky afterwards, so a reader that oddly resumes after failing can never
216	// let the snapshot be applied once a failure has been reported, and a later
217	// clean io.EOF cannot erase a fault already received.
218	type snapshotReader struct {
219		r       io.Reader
220		fault   error // first error other than the bare io.EOF reported by r, if any
221		pending bool  // fault is due on the next read
222	}
223	
224	func (s *snapshotReader) Read(p []byte) (int, error) {
225		if s.pending {
226			s.pending = false
227			return 0, s.fault
228		}
229		if s.fault != nil {
230			return 0, s.fault
231		}
232		n, err := s.r.Read(p)
233		// Identity comparison on purpose: the JSON decoder treats only the bare
234		// io.EOF as the normal end of input the same way. A wrapped io.EOF, or a
235		// combined error carrying io.EOF alongside a storage fault, must reach
236		// the fault path instead of passing for a clean end.
237		if err == nil || err == io.EOF {
238			return n, err
239		}
240		if s.fault == nil {
241			s.fault = err
242		}
243		if n > 0 {
244			s.pending = true
245			return n, nil
246		}
247		return 0, err
248	}
249	
250	// parseSnapshot reads and fully validates one snapshot document. It returns
251	// the tip height and the validated blocks in ascending height order.
252	func parseSnapshot(r io.Reader) (int64, []Block, error) {
253		// A fault the underlying reader reports mid-document — including one
254		// delivered together with usable bytes — is observed via snapshotReader
255		// rather than inferred from the JSON decoder, which would conflate it with
256		// a clean io.EOF on truncated input.
257		reader := &snapshotReader{r: r}
258		dec := json.NewDecoder(reader)
259		// classify maps a decoder failure onto the snapshot error model, but a
260		// fault observed on the underlying reader always wins: the decoder turns a
261		// clean io.EOF after truncated input into io.ErrUnexpectedEOF, so the
262		// presence of a real reader fault is the only reliable way to tell a read
263		// failure from an honestly truncated document. Field context carried by
264		// err (for example which field was being read) is preserved, and the
265		// recorded fault stays in the chain even when the decoder reports a
266		// separate content error from bytes already buffered.
267		classify := func(err error) error {
268			if reader.fault == nil {
269				return classifySnapshotErr(err)
270			}
271			if !errors.Is(err, reader.fault) {
272				err = fmt.Errorf("%w: %v", reader.fault, err)
273			}
274			return fmt.Errorf("indexroom: read snapshot: %w", err)
275		}
276		// reject reports a content error found in bytes already decoded, unless
277		// the underlying reader has already reported a fault: a stream that
278		// failed cannot be known to be complete, so the read failure takes
279		// precedence over any content error the same batch of bytes exposed —
280		// even over a complete, otherwise valid snapshot. Only a fault already
281		// observed wins; content errors found before the reader has failed are
282		// reported as-is, without reading ahead to look for one.
283		reject := func(err error) error {
284			if reader.fault != nil {
285				return fmt.Errorf("indexroom: read snapshot: %w", reader.fault)
286			}
287			return err
288		}
289		tok, err := dec.Token()
290		if err != nil {
291			return 0, nil, classify(err)
292		}
293		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
294			return 0, nil, reject(invalidSnapshot("snapshot must be a single JSON object"))
295		}
296	
297		// Top-level fields are captured raw so blocks can be parsed with the
298		// strict schema matching the declared version, whatever the field order,
299		// and so null can be told apart from a zero value.
300		var (
301			rawVersion, rawTip   json.RawMessage
302			rawBlocks            json.RawMessage
303			haveVersion, haveTip bool
304			haveBlocks           bool
305			seen                 = map[string]bool{}
306		)
307		for dec.More() {
308			key, err := snapshotKey(dec)
309			if err != nil {
310				return 0, nil, classify(err)
311			}
312			if seen[key] {
313				return 0, nil, reject(invalidSnapshot("duplicate field %q", key))
314			}
315			seen[key] = true
316			switch key {
317			case "version":
318				if err := dec.Decode(&rawVersion); err != nil {
319					return 0, nil, classify(fmt.Errorf("field %q: %w", key, err))
320				}
321				haveVersion = true
322			case "tip":
323				if err := dec.Decode(&rawTip); err != nil {
324					return 0, nil, classify(fmt.Errorf("field %q: %w", key, err))
325				}
326				haveTip = true
327			case "blocks":
328				if err := dec.Decode(&rawBlocks); err != nil {
329					return 0, nil, classify(fmt.Errorf("field %q: %w", key, err))
330				}
331				haveBlocks = true
332			default:
333				return 0, nil, reject(invalidSnapshot("unknown field %q", key))
334			}
335		}
336		if _, err := dec.Token(); err != nil { // closing '}'
337			return 0, nil, classify(err)
338		}
339		// Only whitespace may follow the snapshot object. A reader fault that
340		// arrived together with the document's final bytes is held back by
341		// snapshotReader and surfaces here, ahead of any content validation below:
342		// once the stream failed, the document cannot be known to be complete, so
343		// the read failure takes precedence even when the buffered bytes already
344		// contain trailing data or a complete object.
345		if reader.fault != nil {
346			return 0, nil, fmt.Errorf("indexroom: read snapshot: %w", reader.fault)
347		}
348		if _, err := dec.Token(); err != io.EOF {
349			if err == nil {
350				// The read that fetched the trailing bytes may itself have
351				// reported a fault; that failure still outranks the extra data.
352				return 0, nil, reject(invalidSnapshot("trailing data after the snapshot object"))
353			}
354			return 0, nil, classify(err)
355		}
356	
357		if !haveVersion {
358			return 0, nil, invalidSnapshot("missing field %q", "version")
359		}
360		if !haveTip {
361			return 0, nil, invalidSnapshot("missing field %q", "tip")
362		}
363		if !haveBlocks {
364			return 0, nil, invalidSnapshot("missing field %q", "blocks")
365		}
366		version, err := snapshotInt64(rawVersion, "version")
367		if err != nil {
368			return 0, nil, err
369		}
370		tip, err := snapshotInt64(rawTip, "tip")
371		if err != nil {
372			return 0, nil, err
373		}
374		if version != snapshotVersion1 && version != snapshotVersion2 {
375			return 0, nil, invalidSnapshot("unsupported version %d", version)
376		}
377	
378		blockDec := json.NewDecoder(bytes.NewReader(rawBlocks))
379		blocks, err := parseSnapshotBlocks(blockDec, version)
380		if err != nil {
381			return 0, nil, err
382		}
383		if _, err := blockDec.Token(); err != io.EOF {
384			if err == nil {
385				return 0, nil, invalidSnapshot("trailing data after the blocks array")
386			}
387			return 0, nil, classifySnapshotErr(err)
388		}
389	
390		lastHeight := int64(0)
391		if len(blocks) > 0 {
392			lastHeight = blocks[len(blocks)-1].Height
393		}
394		if tip != lastHeight {
395			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
396		}
397		return tip, blocks, nil
398	}
399	
400	// parseSnapshotBlocks reads the blocks array value, validating heights,
401	// hashes, parent links, and (for version 2) timestamps as it goes.
402	func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
403		tok, err := dec.Token()
404		if err != nil {
405			return nil, classifySnapshotErr(err)
406		}
407		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
408			return nil, invalidSnapshot("field %q must be an array", "blocks")
409		}
410		blocks := []Block{}
411		seenHash := map[string]bool{}
412		for dec.More() {
413			var block Block
414			if version == snapshotVersion2 {
415				block, err = parseSnapshotBlockV2(dec)
416			} else {
417				block, err = parseSnapshotBlock(dec)
418			}
419			if err != nil {
420				return nil, err
421			}
422			want := int64(len(blocks) + 1)
423			if block.Height != want {
424				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
425			}
426			if block.Hash == "" {
427				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
428			}
429			if seenHash[block.Hash] {
430				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
431			}
432			seenHash[block.Hash] = true
433			// The first block's parent names the chain start and is exempt from
434			// linkage; every later block must point at its predecessor.
435			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
436				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
437			}
438			blocks = append(blocks, block)
439		}
440		if _, err := dec.Token(); err != nil { // closing ']'
441			return nil, classifySnapshotErr(err)
442		}
443		return blocks, nil
444	}
445	
446	// parseSnapshotBlock reads one version-1 block object, requiring exactly the
447	// fields height, hash, parent, and txs.
448	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
449		var block Block
450		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs")
451		if err != nil {
452			return block, err
453		}
454		return finishSnapshotBlock(fields)
455	}
456	
457	// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
458	// the fields height, hash, parent, txs, and timestamp. Timestamp must be
459	// null or a non-negative integer; the block returns a nil time for null.
460	func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
461		var block Block
462		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs", "timestamp")
463		if err != nil {
464			return block, err
465		}
466		if _, ok := fields["timestamp"]; !ok {
467			return block, invalidSnapshot("block is missing field %q", "timestamp")
468		}
469		block, err = finishSnapshotBlock(fields)
470		if err != nil {
471			return block, err
472		}
473		t, err := parseSnapshotTimestamp(fields["timestamp"])
474		if err != nil {
475			return Block{}, err
476		}
477		block.Time = t
478		return block, nil
479	}
480	
481	// readSnapshotBlockObject reads one block object and captures each known
482	// field's raw value. Fields are decoded only after the whole object is read,
483	// so a null can be rejected per field and a txs element error can name the
484	// block's height whatever order the fields arrive in.
485	func readSnapshotBlockObject(dec *json.Decoder, known ...string) (map[string]json.RawMessage, error) {
486		tok, err := dec.Token()
487		if err != nil {
488			return nil, classifySnapshotErr(err)
489		}
490		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
491			return nil, invalidSnapshot("block must be a JSON object")
492		}
493		fields := map[string]json.RawMessage{}
494		for dec.More() {
495			key, err := snapshotKey(dec)
496			if err != nil {
497				return nil, classifySnapshotErr(err)
498			}
499			if _, dup := fields[key]; dup {
500				return nil, invalidSnapshot("duplicate block field %q", key)
501			}
502			if !slices.Contains(known, key) {
503				return nil, invalidSnapshot("unknown block field %q", key)
504			}
505			var raw json.RawMessage
506			if err := dec.Decode(&raw); err != nil {
507				return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
508			}
509			fields[key] = raw
510		}
511		if _, err := dec.Token(); err != nil { // closing '}'
512			return nil, classifySnapshotErr(err)
513		}
514		return fields, nil
515	}
516	
517	// finishSnapshotBlock decodes the shared block fields from their raw values,
518	// requiring height, hash, parent, and txs and rejecting null for each.
519	func finishSnapshotBlock(fields map[string]json.RawMessage) (Block, error) {
520		var block Block
521		for _, field := range []string{"height", "hash", "parent", "txs"} {
522			if _, ok := fields[field]; !ok {
523				return block, invalidSnapshot("block is missing field %q", field)
524			}
525		}
526		var err error
527		if block.Height, err = snapshotInt64(fields["height"], "height"); err != nil {
528			return block, err
529		}
530		if block.Hash, err = snapshotString(fields["hash"], "hash", block.Height); err != nil {
531			return block, err
532		}
533		if block.Parent, err = snapshotString(fields["parent"], "parent", block.Height); err != nil {
534			return block, err
535		}
536		txs, err := parseSnapshotTxs(json.NewDecoder(bytes.NewReader(fields["txs"])), block.Height)
537		if err != nil {
538			return block, err
539		}
540		block.Txs = txs
541		return block, nil
542	}
543	
544	// snapshotInt64 decodes one required integer field, rejecting null rather
545	// than letting it pass as zero.
546	func snapshotInt64(raw json.RawMessage, field string) (int64, error) {
547		if isSnapshotNull(raw) {
548			return 0, invalidSnapshot("field %q must not be null", field)
549		}
550		var v int64
551		if err := json.Unmarshal(raw, &v); err != nil {
552			return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
553		}
554		return v, nil
555	}
556	
557	// snapshotString decodes one required string field, rejecting null rather
558	// than letting it pass as the empty string. The raw literal is also checked
559	// for invalid UTF-8 bytes and unpaired or misordered \uXXXX surrogate
560	// escapes, which the decoder would otherwise silently rewrite to U+FFFD;
561	// height identifies the block the field belongs to in the error.
562	func snapshotString(raw json.RawMessage, field string, height int64) (string, error) {
563		if isSnapshotNull(raw) {
564			return "", invalidSnapshot("field %q must not be null", field)
565		}
566		var s string
567		if err := json.Unmarshal(raw, &s); err != nil {
568			return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
569		}
570		if !validSnapshotString(raw) {
571			return "", invalidSnapshot("block at height %d: field %q has invalid UTF-8 or unpaired surrogate escapes", height, field)
572		}
573		return s, nil
574	}
575	
576	// isSnapshotNull reports whether a raw field value is the JSON null literal.
577	func isSnapshotNull(raw json.RawMessage) bool {
578		return string(raw) == "null"
579	}
580	
581	// validSnapshotString reports whether raw is a JSON string literal whose
582	// content is valid UTF-8 and whose \uXXXX escapes contain no unpaired or
583	// misordered surrogates. The JSON decoder accepts both defects silently,
584	// rewriting the bad parts to U+FFFD, which could merge distinct identifiers;
585	// the raw bytes are checked here before the decoded value is trusted. A
586	// genuine U+FFFD — written literally or as a \ufffd escape — is valid
587	// UTF-8 and passes.
588	func validSnapshotString(raw json.RawMessage) bool {
589		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
590			return false
591		}
592		body := raw[1 : len(raw)-1]
593		for i := 0; i < len(body); {
594			b := body[i]
595			switch {
596			case b == '\\':
597				if i+1 >= len(body) {
598					return false
599				}
600				if body[i+1] != 'u' {
601					i += 2 // \", \\, \/, \b, \f, \n, \r, \t
602					continue
603				}
604				code, ok := snapshotHex4(body, i+2)
605				if !ok {
606					return false
607				}
608				i += 6
609				switch {
610				case code >= 0xD800 && code <= 0xDBFF:
611					// A high surrogate is only valid as the first half of a
612					// pair; the low half must follow immediately as an escape.
613					if i+6 > len(body) || body[i] != '\\' || body[i+1] != 'u' {
614						return false
615					}
616					low, ok := snapshotHex4(body, i+2)
617					if !ok || low < 0xDC00 || low > 0xDFFF {
618						return false
619					}
620					i += 6
621				case code >= 0xDC00 && code <= 0xDFFF:
622					return false // a low surrogate cannot appear on its own
623				}
624			case b < utf8.RuneSelf:
625				i++
626			default:
627				// DecodeRune returns RuneError with size 1 for invalid
628				// encoding; a genuine U+FFFD decodes with size 3.
629				r, size := utf8.DecodeRune(body[i:])
630				if r == utf8.RuneError && size <= 1 {
631					return false
632				}
633				i += size
634			}
635		}
636		return true
637	}
638	
639	// snapshotHex4 reads four hexadecimal digits starting at b[i].
640	func snapshotHex4(b []byte, i int) (rune, bool) {
641		if i+4 > len(b) {
642			return 0, false
643		}
644		var v rune
645		for _, c := range b[i : i+4] {
646			var d byte
647			switch {
648			case '0' <= c && c <= '9':
649				d = c - '0'
650			case 'a' <= c && c <= 'f':
651				d = c - 'a' + 10
652			case 'A' <= c && c <= 'F':
653				d = c - 'A' + 10
654			default:
655				return 0, false
656			}
657			v = v*16 + rune(d)
658		}
659		return v, true
660	}
661	
662	// parseSnapshotTimestamp reads one timestamp value: null for a missing
663	// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
664	// distinct from null.
665	func parseSnapshotTimestamp(raw json.RawMessage) (*int64, error) {
666		var t *int64
667		if err := json.Unmarshal(raw, &t); err != nil {
668			return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
669		}
670		if t != nil && *t < 0 {
671			return nil, invalidSnapshot("timestamp must not be negative")
672		}
673		return t, nil
674	}
675	
676	// parseSnapshotTxs reads one txs array, preserving duplicates and empty
677	// identifiers exactly as written. A null element is rejected, naming the
678	// block's height and the element's zero-based position, and so is an
679	// element whose raw string carries invalid UTF-8 bytes or unpaired or
680	// misordered surrogate escapes.
681	func parseSnapshotTxs(dec *json.Decoder, height int64) ([]string, error) {
682		tok, err := dec.Token()
683		if err != nil {
684			return nil, classifySnapshotErr(err)
685		}
686		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
687			return nil, invalidSnapshot("field %q must be an array of strings", "txs")
688		}
689		txs := []string{}
690		for dec.More() {
691			var raw json.RawMessage
692			if err := dec.Decode(&raw); err != nil {
693				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
694			}
695			if isSnapshotNull(raw) {
696				return nil, invalidSnapshot("block at height %d: txs element %d must not be null", height, len(txs))
697			}
698			var tx string
699			if err := json.Unmarshal(raw, &tx); err != nil {
700				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
701			}
702			if !validSnapshotString(raw) {
703				return nil, invalidSnapshot("block at height %d: field %q element %d has invalid UTF-8 or unpaired surrogate escapes", height, "txs", len(txs))
704			}
705			txs = append(txs, tx)
706		}
707		if _, err := dec.Token(); err != nil { // closing ']'
708			return nil, classifySnapshotErr(err)
709		}
710		return txs, nil
711	}
712	
713	// snapshotKey reads the next object key and returns the decoder's error
714	// unwrapped so each caller can classify it against its own input source.
715	func snapshotKey(dec *json.Decoder) (string, error) {
716		tok, err := dec.Token()
717		if err != nil {
718			return "", err
719		}
720		key, ok := tok.(string)
721		if !ok {
722			return "", invalidSnapshot("object key must be a string")
723		}
724		return key, nil
725	}
726	
727	// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
728	func invalidSnapshot(format string, args ...any) error {
729		return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
730	}
731	
732	// classifySnapshotErr maps decoder failures onto the snapshot error model:
733	// malformed JSON, wrong value types, and truncation are snapshot errors,
734	// while anything else is an underlying read failure reported as-is.
735	func classifySnapshotErr(err error) error {
736		var syntaxErr *json.SyntaxError
737		var typeErr *json.UnmarshalTypeError
738		switch {
739		case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
740			return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
741		case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
742			return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
743		default:
744			return fmt.Errorf("indexroom: read snapshot: %w", err)
745		}
746	}
747

