95	// QueryTxs searches the main chain for transaction occurrences matching the
96	// query. Every call observes one complete chain state: concurrent Append or
97	// Reorg calls never leak into a page, and the returned records are copies
98	// the caller may freely mutate. The query itself never modifies the index.
99	//
100	// The first page (empty Cursor) pins the filtered range and returns a
101	// continuation cursor while more results remain. Continuations reuse the
102	// pinned range — blocks appended above it are invisible to the query — and
103	// succeed as long as every block inside the range still matches the first
104	// page; otherwise they fail with ErrQueryChanged.
105	func (index *Index) QueryTxs(query TxQuery) (TxPage, error) {
106		pageSize, err := normalizePageSize(query.PageSize)
107		if err != nil {
108			return TxPage{}, err
109		}
110		if query.Cursor != "" {
111			return index.continueQuery(query, pageSize)
112		}
113		return index.firstQuery(query, pageSize)
