390		first, err := index.QueryTxs(TxQuery{PageSize: 1})
391		if err != nil {
392			t.Fatal(err)
393		}
394		cursor := first.NextCursor
395		if cursor == "" {
396			t.Fatal("expected a continuation cursor")
397		}
398		blocks, byHash, tip := snapshot(index)
399	
400		err = index.Restore(&oneShotReader{
401			data: []byte(oneBlockV1),
402			err:  errors.Join(io.EOF, errStorageOffline),
403		})
404		if err == nil {
405			t.Fatal("expected a read failure, got success")
406		}
407		if errors.Is(err, ErrInvalidSnapshot) {
408			t.Fatalf("err=%v, must not be ErrInvalidSnapshot", err)
409		}
410		if !errors.Is(err, io.EOF) || !errors.Is(err, errStorageOffline) {
411			t.Fatalf("err=%v, want errors.Is both io.EOF and the storage fault", err)
412		}
413		requireUnchanged(t, index, blocks, byHash, tip)
414	
415		pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: cursor})
416		var all []TxHit
417		for _, page := range pages {
418			all = append(all, page.Hits...)
419		}
420		want := []TxHit{
421			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
422			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
423		}
424		if !reflect.DeepEqual(all, want) {
425			t.Fatalf("hits after read failure=%v, want %v", all, want)
426		}
427	}
428	
429	// A fault already received is sticky: even if the underlying stream then
430	// "recovers", delivers the bytes that complete the document, and ends with a
431	// clean io.EOF, the failure cannot be erased and the snapshot is not applied.
432	func TestRestoreFaultNotErasedByLaterCleanEOF(t *testing.T) {
433		index := txChain(t, []string{"a"}, []string{"b"})
434		blocks, byHash, tip := snapshot(index)
435		r := &scriptReader{chunks: []scriptChunk{
436			// The prefix arrives together with the combined fault.
437			{data: halfSnapshot, err: errors.Join(io.EOF, errStorageOffline)},
438			// The reader then oddly resumes with the rest of the document...
439			{data: `[]]}`},
440			// ...and finally signals a clean end.
441		}}
442		err := index.Restore(r)
443		if errors.Is(err, ErrInvalidSnapshot) {
444			t.Fatalf("err=%v, must not be ErrInvalidSnapshot", err)
445		}
446		if !errors.Is(err, io.EOF) || !errors.Is(err, errStorageOffline) {
447			t.Fatalf("err=%v, want the first fault preserved, not erased by the clean EOF", err)
448		}
449		requireUnchanged(t, index, blocks, byHash, tip)
450	}
451	
452	// Fault/content precedence with combined EOF errors: a content error exposed
453	// by the same batch of bytes that already carries a read fault yields the read
454	// failure; a content error found while the reader has not yet reported any
455	// fault rejects the snapshot as invalid immediately, without consuming the
456	// joined EOF+fault that comes next.
457	func TestRestoreJoinedEOFPrecedenceAndEarlyReject(t *testing.T) {
458		contentBad := `{"version":1,"tip":0,"blocks":[],"extra":0}`
459	
460		t.Run("fault already reported outranks content error", func(t *testing.T) {
461			index := txChain(t, []string{"a"}, []string{"b"})
462			blocks, byHash, tip := snapshot(index)
463			err := index.Restore(&oneShotReader{
464				data: []byte(contentBad),
465				err:  errors.Join(io.EOF, errStorageOffline),
466			})
467			if errors.Is(err, ErrInvalidSnapshot) {
468				t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
469			}
470			if !errors.Is(err, io.EOF) || !errors.Is(err, errStorageOffline) {
471				t.Fatalf("err=%v, want errors.Is io.EOF and the storage fault", err)
472			}
473			requireUnchanged(t, index, blocks, byHash, tip)
474		})
475	
476		t.Run("content error first rejects without reading ahead", func(t *testing.T) {
477			index := txChain(t, []string{"a"}, []string{"b"})
478			blocks, byHash, tip := snapshot(index)
479			err := index.Restore(&scriptReader{chunks: []scriptChunk{
480				{data: contentBad},
481				{err: errors.Join(io.EOF, errStorageOffline)},
482			}})
483			if !errors.Is(err, ErrInvalidSnapshot) {
484				t.Fatalf("err=%v, want ErrInvalidSnapshot", err)
485			}
486			if errors.Is(err, errStorageOffline) || errors.Is(err, io.EOF) {
487				t.Fatalf("err=%v, must not consume the stream looking for a fault", err)
488			}
489			requireUnchanged(t, index, blocks, byHash, tip)
490		})
491	}
492	
493	// Both supported snapshot versions keep the same EOF rule: a combined
494	// io.EOF+fault ending is a read failure, while the same documents ending with
495	// a bare, direct io.EOF still restore successfully.
496	func TestRestoreJoinedEOFReadFailureBothVersions(t *testing.T) {
497		for name, doc := range map[string]string{"version 1": oneBlockV1, "version 2": oneBlockV2} {
498			t.Run(name, func(t *testing.T) {
499				index := txChain(t, []string{"a"}, []string{"b"})
500				blocks, byHash, tip := snapshot(index)
501				err := index.Restore(&oneShotReader{
502					data: []byte(doc),
503					err:  errors.Join(io.EOF, errStorageOffline),
504				})
505				if errors.Is(err, ErrInvalidSnapshot) {
506					t.Fatalf("fault: err=%v, must not be ErrInvalidSnapshot", err)
507				}
508				if !errors.Is(err, io.EOF) || !errors.Is(err, errStorageOffline) {
509					t.Fatalf("fault: err=%v, want errors.Is io.EOF and the storage fault", err)
510				}
511				requireUnchanged(t, index, blocks, byHash, tip)
512	
513				// The identical document ending with a bare io.EOF still applies.
514				if err := index.Restore(strings.NewReader(doc)); err != nil {
515					t.Fatalf("clean EOF restore failed: %v", err)
516				}
517				if index.Tip != 1 || index.ByHash["g1"] != 1 {
518					t.Fatalf("clean restore did not apply the one-block chain: tip=%d byHash=%v", index.Tip, index.ByHash)
519				}
520			})
521		}
