109	// restoreFilteredHits is the filtered oracle: every matching occurrence in
110	// chain in height/position order, plus the number of blocks holding a match.
111	// It is derived from the supplied chain, not from the Index under test.
112	func restoreFilteredHits(chain []Block, ids []string) (hits []TxHit, blocks int64) {
113		filter := make(map[string]struct{}, len(ids))
114		for _, id := range ids {
115			filter[id] = struct{}{}
116		}
117		hits = []TxHit{}
118		for _, block := range chain {
119			matched := false
120			for position, tx := range block.Txs {
121				if _, ok := filter[tx]; !ok {
122					continue
123				}
124				hits = append(hits, TxHit{
125					Height:    block.Height,
126					BlockHash: block.Hash,
127					TxID:      tx,
128					Position:  position,
129				})
130				matched = true
131			}
132			if matched {
133				blocks++
134			}
135		}
136		return hits, blocks
137	}
