186	// The counting and ordering semantics the regression rests on, asserted for
187	// each chain and cross-checked against the live index before and after the
188	// restore.
189	func TestRestoreQueryTxsFixtureSemanticsOnBothChains(t *testing.T) {
190		oldChain := restoreQueryOldChainBlocks()
191		newChain := restoreQueryNewChainBlocks()
192	
193		oldHits, oldBlocks := restoreFilteredHits(oldChain, restoreTxQuery.TxIDs)
194		wantOld := []TxHit{
195			{Height: 1, BlockHash: "h1", TxID: "x", Position: 0},
196			{Height: 1, BlockHash: "h1", TxID: "x", Position: 2},
197			{Height: 3, BlockHash: "h3", TxID: "y", Position: 1},
198			{Height: 4, BlockHash: "h4", TxID: "x", Position: 2},
199			{Height: 4, BlockHash: "h4", TxID: "y", Position: 3},
200			{Height: 4, BlockHash: "h4", TxID: "y", Position: 4},
201			{Height: 5, BlockHash: "h5", TxID: "y", Position: 0},
202		}
203		if !reflect.DeepEqual(oldHits, wantOld) {
204			t.Fatalf("old filtered hits=%v, want %v", oldHits, wantOld)
205		}
206		if oldBlocks != 4 {
207			t.Fatalf("old matched blocks=%d, want 4 (h1,h3,h4,h5)", oldBlocks)
208		}
209	
210		newHits, newBlocks := restoreFilteredHits(newChain, restoreTxQuery.TxIDs)
211		wantNew := []TxHit{
212			{Height: 1, BlockHash: "j1", TxID: "x", Position: 0},
213			{Height: 1, BlockHash: "j1", TxID: "y", Position: 1},
214			{Height: 4, BlockHash: "j4", TxID: "y", Position: 0},
215			{Height: 4, BlockHash: "j4", TxID: "y", Position: 1},
216			{Height: 4, BlockHash: "j4", TxID: "x", Position: 3},
217		}
218		if !reflect.DeepEqual(newHits, wantNew) {
219			t.Fatalf("new filtered hits=%v, want %v", newHits, wantNew)
220		}
221		if newBlocks != 2 {
222			t.Fatalf("new matched blocks=%d, want 2 (j1,j4)", newBlocks)
223		}
224	
225		// Setup invariants that make old/new/mixture answers distinguishable.
226		//
227		// Every overlap height carries different content under a different hash;
228		// a removed height holds an only-old match, and the shorter chain carries
229		// only-new matches. Restore replaces height 1 as well, so the chains
230		// share no block hash and no record is explainable by both chains.
231		if containsHit(newHits, TxHit{Height: 5, BlockHash: "h5", TxID: "y", Position: 0}) {
232			t.Fatal("removed-height match y@h5 must not exist on the new chain")
233		}
234		if !containsHit(oldHits, TxHit{Height: 5, BlockHash: "h5", TxID: "y", Position: 0}) {
235			t.Fatal("old chain must keep y@h5, the match confined to a removed height")
236		}
237		if !containsHit(newHits, TxHit{Height: 4, BlockHash: "j4", TxID: "y", Position: 1}) {
238			t.Fatal("new chain must keep its only-new y@j4#1 occurrence")
239		}
240		if containsHit(oldHits, TxHit{Height: 4, BlockHash: "j4", TxID: "y", Position: 1}) {
241			t.Fatal("j4 occurrence must not exist on the old chain")
242		}
243		// Duplicate matching ids survive with multiplicity, exact position, and
244		// the block hash of the observed chain.
245		if !containsHit(oldHits, TxHit{Height: 1, BlockHash: "h1", TxID: "x", Position: 2}) ||
246			!containsHit(newHits, TxHit{Height: 4, BlockHash: "j4", TxID: "y", Position: 1}) {
247			t.Fatal("duplicate in-block matching ids must be kept by occurrence")
248		}
249		requireOrdered(t, oldHits)
250		requireOrdered(t, newHits)
251	
252		// The three counts must not coincide on either chain, so correct records
253		// cannot mask statistics drawn from the wrong chain.
254		pageLen := int64(restoreTxPageSize)
255		for name, totals := range map[string][2]int64{
256			"old": {int64(len(oldHits)), oldBlocks},
257			"new": {int64(len(newHits)), newBlocks},
258		} {
259			if totals[0] == totals[1] || totals[0] == pageLen || totals[1] == pageLen {
260				t.Fatalf("%s chain setup: total=%d blocks=%d page=%d must all differ",
261					name, totals[0], totals[1], pageLen)
262			}
263		}
264		if int64(len(oldHits)) == int64(len(newHits)) || oldBlocks == newBlocks {
265			t.Fatal("old and new totals must differ so the complete answers are distinct")
266		}
267		// First pages leave matches unpaginated on both chains, and statistics
268		// span the whole range rather than the page.
269		if int64(len(literalRestoreTxOldFirstPage().Hits)) != pageLen ||
270			int64(len(literalRestoreTxNewFirstPage().Hits)) != pageLen {
271			t.Fatal("test setup: both literal first pages must be exactly one page long")
272		}
273	
274		// Oracle pages must equal the hand-derived literal pages.
275		if got := restoreReferenceTxPage(oldChain, restoreTxPageSize, 0); !reflect.DeepEqual(got, literalRestoreTxOldFirstPage()) {
276			t.Fatalf("old oracle page=%+v", got)
277		}
278		if got := restoreReferenceTxPage(newChain, restoreTxPageSize, 0); !reflect.DeepEqual(got, literalRestoreTxNewFirstPage()) {
279			t.Fatalf("new oracle page=%+v", got)
280		}
281	
282		// The oracle must match the live index on both complete chain states.
283		index := buildRestoreQueryOldChain(t)
284		live, err := index.QueryTxs(restoreTxQuery)
285		if err != nil {
286			t.Fatal(err)
287		}
288		if !reflect.DeepEqual(viewOf(live), viewOf(literalRestoreTxOldFirstPage())) {
289			t.Fatalf("live old-chain query=%+v, want literal old first page", live)
290		}
291		if live.NextCursor == "" {
292			t.Fatal("old first page over 7 matches with page size 3 must carry a cursor")
293		}
294	
295		if err := index.Restore(strings.NewReader(restoreTxNewSnapshot)); err != nil {
296			t.Fatalf("restore refused: %v", err)
297		}
298		if index.Tip != 4 {
299			t.Fatalf("tip after restore=%d, want 4", index.Tip)
300		}
301		live, err = index.QueryTxs(restoreTxQuery)
302		if err != nil {
303			t.Fatal(err)
304		}
305		if !reflect.DeepEqual(viewOf(live), viewOf(literalRestoreTxNewFirstPage())) {
306			t.Fatalf("live new-chain query=%+v, want literal new first page", live)
307		}
308		if live.NextCursor == "" {
309			t.Fatal("new first page over 5 matches with page size 3 must carry a cursor")
310		}
311	}
