423		// Park the read just before the second (poisoned) block: the first block
424		// of the snapshot has been fully consumed when the restore stalls.
425		reader := newGatedReader(t, restoreNegativeTimeSnapshot, `{"height":2`)
426	
427		restoreDone := make(chan error, 1)
428		go func() {
429			restoreDone <- index.Restore(reader)
430		}()
431		<-reader.entered
432	
433		stats, err := index.QueryTimeStats(restoreStatsQuery)
434		if err != nil {
435			t.Fatalf("query during gated read failed: %v", err)
436		}
437		if !reflect.DeepEqual(stats, literalRestoreOldStats()) {
438			t.Fatalf("query while the invalid snapshot is still reading must see the old chain:\n%+v", stats)
439		}
440	
441		close(reader.release)
442		if err := <-restoreDone; !errors.Is(err, ErrInvalidSnapshot) {
443			t.Fatalf("restore err=%v, want ErrInvalidSnapshot", err)
444		}
445	
446		// The rejected restore changed nothing: stats still match the old chain
447		// exactly and no partially read snapshot block survived.
448		stats, err = index.QueryTimeStats(restoreStatsQuery)
449		if err != nil {
450			t.Fatal(err)
451		}
452		if !reflect.DeepEqual(stats, literalRestoreOldStats()) {
453			t.Fatalf("stats after rejected restore differ from the old chain:\n%+v", stats)
454		}
455		if index.Tip != 4 || len(index.Blocks) != 4 {
456			t.Fatalf("rejected restore left tip=%d blocks=%d, want tip 4 with 4 blocks", index.Tip, len(index.Blocks))
457		}
458		if index.Blocks[3].Time != nil {
459			t.Fatalf("time-less h3 gained a timestamp from the rejected snapshot: %+v", index.Blocks[3])
460		}
461		for _, hash := range []string{"h1", "h2", "h3", "h4"} {
462			if _, ok := index.ByHash[hash]; !ok {
463				t.Fatalf("old hash %s lost after rejected restore", hash)
464			}
465		}
466		for _, leaked := range []string{"j1", "j2"} {
467			if _, ok := index.ByHash[leaked]; ok {
468				t.Fatalf("hash %s from the rejected snapshot was left indexed", leaked)
469			}
470		}
471		if stats.MissingTimeBlocks != 1 || stats.ToHeight != 4 {
472			t.Fatalf("rejected snapshot altered the missing-time count or upper height: %+v", stats)
473		}
474	}
475	
476	// The complete-chain validator must catch exactly the mixtures this
477	// regression targets: old-chain transaction counts paired with the new
478	// chain's height bound, missing-time count, or dedup result (and vice versa).
479	func TestClassifyTimeStatsRejectsRestoreMixtures(t *testing.T) {
480		oldRef, newRef := literalRestoreOldStats(), literalRestoreNewStats()
481		if err := classifyTimeStats(oldRef, oldRef, newRef); err != nil {
482			t.Fatalf("pure old answer rejected: %v", err)
483		}
484		if err := classifyTimeStats(newRef, oldRef, newRef); err != nil {
485			t.Fatalf("pure new answer rejected: %v", err)
486		}
487	
488		// Old transaction counts and dedup under the NEW upper height.
489		mixed := oldRef
490		mixed.ToHeight = newRef.ToHeight
491		if err := classifyTimeStats(mixed, oldRef, newRef); err == nil {
492			t.Fatal("old counts under the new tip height were accepted")
493		} else if !strings.Contains(err.Error(), "MIXED") {
494			t.Fatalf("old-counts/new-height mixture not reported as MIXED:\n%v", err)
495		}
496	
497		// New transaction counts under the OLD upper height and missing count.
498		mixed = newRef
499		mixed.ToHeight = oldRef.ToHeight
500		mixed.MissingTimeBlocks = oldRef.MissingTimeBlocks
501		if err := classifyTimeStats(mixed, oldRef, newRef); err == nil {
502			t.Fatal("new counts under the old tip and missing count were accepted")
503		} else if !strings.Contains(err.Error(), "MIXED") {
504			t.Fatalf("new-counts/old-height mixture not reported as MIXED:\n%v", err)
505		}
506	
507		// Old per-bucket content with the new chain's dedup result in the totals.
508		mixed = oldRef
509		mixed.Totals.DistinctTxIDs = newRef.Totals.DistinctTxIDs
510		if err := classifyTimeStats(mixed, oldRef, newRef); err == nil {
511			t.Fatal("old buckets with the new dedup total were accepted")
512		}
513	}
514	
515	// Sustained overlap: restores alternate between the old-chain snapshot and
516	// the new-chain snapshot while readers query continuously. Every answer must
517	// classify as one complete chain; success never depends on which side of a
518	// restore a query happened to land. This is a supplement to the deterministic
519	// rendezvous tests above, not a substitute: those pin the interleavings, this
520	// one sweeps for anything they missed.
521	func TestQueryTimeStatsRepeatedRestoresStayConsistent(t *testing.T) {
522		index := buildRestoreOldChain(t)
523		oldSnapshot := exportString(t, index) // version 2: the chain has timestamps
524		oldRef, newRef := literalRestoreOldStats(), literalRestoreNewStats()
525	
526		const restorers = 2
527		const rounds = 40
528		const readers = 4
529		const reads = 80
530	
531		stop := make(chan struct{})
