546					}
547					if err := index.Restore(strings.NewReader(snapshot)); err != nil {
548						t.Errorf("restore failed: %v", err)
549						return
550					}
551				}
552			}(r)
553		}
554		for r := 0; r < readers; r++ {
555			wg.Add(1)
556			go func() {
557				defer wg.Done()
